const j = $input.item.json;
const sc = (v) => Number(String(v || '').trim().charAt(0)) || 0;
const dims = {
  'Data': sc(j['Data Readiness']),
  'Infrastructure': sc(j['Infrastructure Readiness']),
  'Skills': sc(j['Skills Readiness']),
  'Regulation': sc(j['Regulatory Readiness']),
  'Leadership': sc(j['Leadership Support'])
};
const vals = Object.values(dims);
const avg = vals.reduce((a, b) => a + b, 0) / vals.length;
const sorted = Object.entries(dims).sort((a, b) => a[1] - b[1]);
const weakest = sorted.slice(0, 2).map(e => e[0] + ' (' + e[1] + '/5)').join(', ');
const maturity = avg < 2.5 ? 'Beginner' : (avg < 3.5 ? 'Developing' : 'Ready to scale');
const useCase = {
  'Unplanned machine downtime': 'Predictive maintenance',
  'Product quality defects': 'Quality assurance and control',
  'Supply chain disruption': 'Supply chain optimisation',
  'Manual admin and reporting': 'Workflow automation and reporting',
  'Not sure yet': 'Quick data audit to choose the first use-case'
}[j['Biggest Pain Point']] || 'Quick data audit to choose the first use-case';
return { json: {
  submitted_at: new Date().toISOString().replace('T', ' ').slice(0, 19),
  company: j['Company Name'], contact_email: j['Contact Email'],
  industry: j['Industry'], company_size: j['Company Size'],
  scores: dims, scores_text: Object.entries(dims).map(e => e[0] + ': ' + e[1] + '/5').join(', '),
  overall_score: Math.round(avg * 10) / 10, maturity: maturity, weakest_areas: weakest,
  pain_point: j['Biggest Pain Point'], suggested_use_case: useCase, notes: j['Notes'] || ''
} };

